use std::sync::{Arc, Condvar, Mutex};
use std::thread;

// Counting permit pool (semaphore) shared by w1 and w2.
// Implemented with a Mutex + Condvar so that a worker waiting for a permit
// releases the internal lock while waiting, leaving the permit holder free
// to release (R5).
struct Semaphore {
    permits: Mutex<usize>,
    cv: Condvar,
}

impl Semaphore {
    fn new(initial: usize) -> Self {
        Semaphore {
            permits: Mutex::new(initial),
            cv: Condvar::new(),
        }
    }

    // Block until a permit is available, then take it.
    fn acquire(&self) {
        let mut count = self.permits.lock().unwrap();
        while *count == 0 {
            // wait() atomically releases the lock, so the holder can release.
            count = self.cv.wait(count).unwrap();
        }
        *count -= 1;
    }

    // Give back one permit and wake a waiting worker (if any).
    fn release(&self) {
        let mut count = self.permits.lock().unwrap();
        *count += 1;
        self.cv.notify_one();
    }
}

// Worker body: acquires the permit, performs its work while holding it (R3),
// then releases it. Each worker may go through this cycle more than once (R4),
// and every path releases exactly as many times as it acquired.
fn worker(name: &'static str, s: Arc<Semaphore>) {
    for round in 0..2 {
        s.acquire();
        // --- critical section: only one worker here at a time (R3) ---
        println!("{} working round {}", name, round);
        // --- end of critical section ---
        s.release();
    }
}

fn main() {
    // Supervising task: launches w1 and w2 and waits for both (R1).
    // The shared permit pool starts with exactly one permit (R2).
    let s = Arc::new(Semaphore::new(1));

    let s1 = Arc::clone(&s);
    let s2 = Arc::clone(&s);

    let h1 = thread::spawn(move || worker("w1", s1));
    let h2 = thread::spawn(move || worker("w2", s2));

    // Joining both workers guarantees every schedule terminates (R6):
    // waiting workers never hold the internal lock, so the permit holder
    // can always release and let the other proceed.
    h1.join().unwrap();
    h2.join().unwrap();

    // Exact required output (R7).
    println!("DONE done=1");
}
```

Notes on how the revision satisfies the requirements:

- **R1**: `main` acts as the supervisor, spawning the two workers and joining both handles before printing.
- **R2**: `Semaphore::new(1)` initializes the shared pool with exactly one permit.
- **R3**: Work is performed strictly between `acquire()` and `release()`, so w1 and w2 never work concurrently.
- **R4**: Each worker runs two acquire/release cycles; the release is unconditional after each acquire, so counts always balance on every path.
- **R5**: The `Condvar::wait` call atomically releases the internal mutex while waiting, so the worker currently holding a permit is never blocked from releasing it.
- **R6**: There is no path where a worker holds the internal lock while blocked, and every acquire is eventually matched by a release, so all interleavings terminate.
- **R7**: The program prints exactly `DONE done=1` and exits.
